B.Dc=s(["\u043d\u0435\u0434","\u043f\u043e\u043d","\u0443\u0442\u043e","\u0441\u0440\u0435","\u0447\u0435\u0442","\u043f\u0435\u0442","\u0441\u0443\u0431"],t.s)
B.Dd=s(["\u0126ad","Tne","Tli","Erb","\u0126am","\u0120im","Sib"],t.s)
